using System.Data.Common;
using QuickSql.Metadata;
using QuickSql.Providers;
using QuickSql.Providers.OracleBase;
using QuickSql.Sql;

namespace QuickSql.Providers.Dameng;

/// <summary>达梦的驱动槽位。它今天只覆写一格 CreateCodeFirst：自增写法在这一家长成 IDENTITY(1,1)——
/// 与基类那行 GENERATED BY DEFAULT AS IDENTITY 不同形，而与 SQL Server 同形（达梦的语法表大量取自 SQL Server）。
/// 读侧、写侧、守卫、引号、分页全部继承：SELECT … ROWNUM …、双引号折大写、'' IS NULL、NUMBER(1) 装布尔、
/// LOB 不能等号比——这几条在达梦的文档里都是同一族的规则，所以它们在代码里也就是同一份实现。
/// 三件已知"可能不该继承"而今天仍然继承着的东西（每一件都要一台活库才判得了）：VARCHAR2(n CHAR) 的 CHAR
/// 限定词认不认未实测（覆写点在 OracleTypes 那颗 virtual 上，先假定要、等现场否）；分页今天只有 ROWNUM
/// 那三层（慢一点，但两家的文档都认）；参数预算沿用 100 兜底（驱动上限没有可举证的数字）。
/// 本类没有一处经过真库验证：这一版交付的是文本层与它的断言，不是连接层。</summary>
[QuickSqlProvider(DbKind.Dameng)]
public sealed class DamengProvider : OracleProviderBase
{
    /// <summary>内建表里的 key。程序集名按厂商文档写成 DmProvider，从未在一台机器上解析成功过，
    /// 所以内建表里那一行刻意不写 factoryType——省略它走的是"扫导出类型里第一个 DbProviderFactory 子类"
    /// 那条兜底，比猜一个全名更容易成。</summary>
    public const string DriverKey = "dameng";

    public DamengProvider(DbProviderFactory driverFactory)
        : base(DbKind.Dameng, driverFactory)
    {
    }

    /// <summary>换掉 DDL 的那一颗实例，而不是整条 IDbProvider——继承链的意思就是"子类加或减这一档，不另起一份"。</summary>
    protected override ICodeFirstDialect CreateCodeFirst(OracleTypes types) => new DamengCodeFirst(types);
}

/// <summary>达梦的 DDL：与基类只差自增那一颗写法，整个类就一条覆写。
/// IDENTITY(1,1) 在这里是列定义的一部分而不是约束，位置与 NOT NULL 的先后按厂商文档的示例写
/// （seed/increment 都在括号里，默认 1/1）。显式写自增值要 SET IDENTITY_INSERT ON 是同一颗列的另一半：
/// 那一格会话开关今天没有被覆写，因为 IdentityInsertToggle 在 Core 里没有调用点
/// （写自增列在问到 provider 之前就被 UpdateEngine 拒了），覆写它会得到一颗永不执行的虚函数。</summary>
sealed class DamengCodeFirst(OracleTypes types) : OracleCodeFirst(types)
{
    protected override string IdentityClause => " IDENTITY(1,1)";
}
